fun main() {
    val xs = (1..100).toList()
    var sum = 0
    for (round in 1..2) {
        sum += build(xs).sum() + counts(xs)
    }
    println(sum)
    var data: Data? = null
    ::suspended.startCoroutine(xs, Continuation(EmptyCoroutineContext) { data = it.getOrThrow() })
    val d = data!!
    println(d.sum())
    println(d.p90)
}
